parameters.text:
=Create an extensive, deep-dive course at the {{ $('Webhook').item.json.body.difficulty }} level. When making the course, use deeplearning.ai, coursera, edX, Udacity as main sources for the structure of the course and expand upon {{ $json.text }} for the content of the course.

Additional Information from the user :
{{ $('Webhook').item.json.body.comments }}

parameters.jsCode:
let rawData = $input.first().json.output;
// $input.first().json.output
rawData = rawData.replace(/```json/g, '').replace(/```/g, '').trim();

const buffer = Buffer.from(rawData, 'utf8');

return [
  {
    json: {
      fileName: "generated_course.ipynb"
    },
    binary: {
      data: {
        data: buffer.toString('base64'),
        mimeType: 'application/x-ipynb+json',
        fileName: 'generated_course.ipynb',
        fileExtension: 'ipynb'
      }
    }
  }
];

const item = $input.first();
const binaryData = item.binary;
const notes = item.json.notes; // or whatever your notes field is called

const items = [];

for (const key of Object.keys(binaryData)) {
  items.push({
    json: { notes }, // pass notes along with each file
    binary: {
      file: binaryData[key] // normalize to a single "file" key
    }
  });
}

return items;

parameters.text:
=Seperate the given text in logical sections, following the given instructions.

Source material:
{{ $json.text }}

parameters.jsCode:
// Parse the AI's string output into an actual array
const raw = $input.first().json.output;
const sections = JSON.parse(raw);

// Return one n8n item per section
return sections.map(section => ({ json: section }));
